from qb import q, write

PL = ["python-developer", "backend-developer", "full-stack-developer", "mobile-app-developer", "junior-ai-engineer"]
ITEMS = [
    q("python", "easy", ["python"], "What are *args and **kwargs in Python and when are they useful?", "*args collects extra positional arguments into a tuple and **kwargs collects extra keyword arguments into a dictionary. They are useful for flexible functions, wrappers and forwarding arguments to another function.", ["Positional vs keyword extras", "Tuple and dictionary", "Wrappers and forwarding"], ["How do you unpack a list into arguments when calling?"]),
    q("python", "medium", ["exceptions"], "How do try, except, else and finally work in Python and what is wrong with a bare except?", "Code in try runs first, except handles a matching error, else runs when no error happened and finally always runs for cleanup. A bare except hides all errors, including ones you did not expect, so catch specific exceptions.", ["Four blocks and their order", "finally always runs", "Catch specific exceptions"], ["How do you create your own exception class?"]),
    q("python", "medium", ["django"], "Explain Django models, migrations and the admin site, and how a typical view returns JSON.", "Models define tables as classes, migrations apply model changes to the database, and the admin site gives a ready management interface. A view reads request data, queries models and returns a JsonResponse or a Django REST Framework response.", ["Models and migrations", "Admin site", "JSON responses"], ["How do you add a field to an existing table safely?"]),
    q("python", "hard", ["performance"], "A Python endpoint that processes a large list is slow. How do you find and improve the bottleneck?", "Profile with cProfile or a similar tool to find where time goes, then use better data structures such as sets or dictionaries for lookups, avoid repeated work, use generators or vectorised libraries and move heavy work to a background job.", ["Profile first", "Better data structures", "Background jobs for heavy work"], ["When is multiprocessing worth it?"]),
    q("dsa", "easy", ["strings"], "How would you check whether two strings are anagrams and what is the complexity?", "Count the characters of each string with a dictionary or Counter and compare the counts, which is O(n); sorting both strings is simpler but O(n log n). Normalise case and spaces first if required.", ["Count characters", "O(n) vs sorting O(n log n)", "Normalise the input"], ["How would you group a list of words by anagram?"]),
    q("dsa", "medium", ["two-pointers"], "Given a sorted list, how would you find a pair that adds up to a target without extra memory?", "Use two pointers at both ends, move the left one up when the sum is too small and the right one down when it is too large, stopping when they meet. It is O(n) time and O(1) space.", ["Two pointers on sorted data", "Move based on the sum", "O(n) time, O(1) space"], ["Why does this need sorted input?"]),
    q("dsa", "medium", ["linked-list"], "What is a linked list and how do you reverse one?", "A linked list stores items in nodes that each point to the next. To reverse it, walk through it while pointing each node back at the previous one, keeping track of previous, current and next, in O(n) time and O(1) space.", ["Nodes with next pointers", "Track previous, current, next", "O(n) time, O(1) space"], ["How do you detect a cycle?"]),
    q("sql", "medium", ["design"], "Design the tables for an online shop with customers, products and orders. How do you represent the items in one order?", "Use customers, products and orders tables, plus an order_items table linking an order to products with quantity and the price at purchase time, because it is a many-to-many relationship. Add foreign keys and indexes on them.", ["Many-to-many needs a link table", "Store price at purchase", "Foreign keys and indexes"], ["Why not store the product price only in the products table?"]),
    q("sql", "medium", ["aggregation"], "Write the idea of a query that finds the top 3 best-selling products last month.", "Join order items to orders, filter orders to last month, group by product, sum the quantity, order by the sum descending and limit to 3. Decide how to handle ties.", ["Join and filter by date", "GROUP BY with SUM", "ORDER BY and LIMIT"], ["How would you do this per category?"]),
    q("api", "medium", ["security"], "How would you secure an API that a mobile app uses?", "Use HTTPS, authenticate with short-lived tokens, check permissions on the server, validate input, rate limit and avoid trusting data from the app because it can be modified. Keep secrets out of the app because they can be extracted.", ["HTTPS and tokens", "Server-side permission checks", "Do not trust the client or store secrets in it"], ["How does a refresh token help?"]),
    q("flutter-mobile", "medium", ["mobile"], "What is state management in a mobile app and how would you organise it for a shopping cart?", "State management decides where app data lives and how screens update when it changes. For a cart, keep it in one shared place, such as a provider, bloc or store, so every screen sees the same data, persist it locally and sync with the server.", ["Shared state for shared data", "Update screens on change", "Persist and sync"], ["What goes wrong if each screen keeps its own copy?"]),
    q("flutter-mobile", "easy", ["mobile"], "What is the difference between stateless and stateful widgets in Flutter?", "A stateless widget does not change after it is built, while a stateful widget holds data that can change and rebuilds when setState is called. Choose stateless unless the widget owns changing data.", ["Immutable vs changing", "setState triggers rebuild", "Prefer stateless"], ["Where should shared state live instead of a widget?"]),
    q("ai", "easy", ["chatbot"], "How does a basic customer support chatbot using an LLM work and what are its limits?", "The app sends the user's message and some context to an LLM and returns the reply. Its limits are wrong answers, no knowledge of private data without retrieval, cost and the need for a handover to a human.", ["Message plus context to an LLM", "Can be wrong or lack private data", "Human handover"], ["How would you stop it answering off-topic questions?"], roles=PL),
    q("ai", "medium", ["prompting", "validation"], "How would you make an LLM return data in a fixed JSON format your code can rely on?", "Ask for the exact schema in the prompt, use the provider's structured output feature if available, parse and validate the result, and retry or fall back when it does not match.", ["Describe the schema", "Parse and validate", "Retry or fall back"], ["What happens to your app if you skip validation?"], roles=PL),
    q("ai", "hard", ["evaluation"], "How would you evaluate and monitor an LLM feature after it is released?", "Build a test set of real questions with expected behaviour, score answers with rules, human review and cautious model-based grading, track failures, cost and latency in production and review user feedback. Re-run the tests whenever the prompt or model changes.", ["Test set and scoring", "Production monitoring", "Re-test on every change"], ["How would you detect a drop in quality?"], roles=PL),
    q("cloud", "medium", ["serverless"], "What is serverless computing, for example AWS Lambda, and when is it a good or poor fit?", "Serverless runs your function on demand and charges per use without managing servers. It fits spiky or event-driven work, but cold starts, time limits and hard-to-debug distributed behaviour make it a poor fit for long-running or latency-critical tasks.", ["Functions on demand", "Good for spiky, event-driven work", "Cold starts and limits"], ["How do you manage secrets in Lambda?"]),
    q("cloud", "medium", ["deployment"], "How would you deploy a Python web app to the cloud with a database, and what do you need for it to survive a server failure?", "Run the app in a managed service or container behind a load balancer with at least two instances, use a managed database with backups and automatic failover, keep sessions and files outside the instance and add health checks and monitoring.", ["Two or more instances", "Managed database with backups", "Stateless app and health checks"], ["How would you test your recovery plan?"]),
    q("cloud", "hard", ["cost"], "Your cloud bill doubled this month. How do you investigate and reduce it?", "Break the bill down by service and tag to find the growth, check for idle or oversized resources, unbounded logs or storage and heavy data transfer, then right-size, set lifecycle rules and add budgets and alerts.", ["Break down the bill", "Find idle and oversized resources", "Budgets and alerts"], ["How would you prevent a surprise next time?"]),
    q("security", "easy", ["passwords"], "How should an application store user passwords and what is a salt?", "Store a slow salted hash made with bcrypt or argon2, never the password itself. A salt is random data added to each password before hashing so identical passwords give different hashes and precomputed tables are useless.", ["Slow salted hash", "Never reversible storage", "Salt defeats precomputed tables"], ["Why is plain SHA-256 a poor choice?"]),
    q("testing", "medium", ["testing"], "What should you test in a new API endpoint before you call it finished?", "Test the normal case, invalid input, missing authentication or permissions, edge values and error responses, check database results and add the tests to the pipeline. A regression test goes with every bug fix.", ["Normal and invalid cases", "Permissions", "Automated in the pipeline"], ["How do you decide when you have tested enough?"]),
    q("pl-scenario", "medium", ["debugging"], "Scenario: the mobile app shows old data after a user updates their profile. How do you find the cause?", "Check whether the update request succeeded, whether the server stores it, and whether the app or an API cache returns an old copy. Fix cache invalidation or refresh the local state after the update and add a test.", ["Trace the request end to end", "Look at caches", "Refresh state after update"], ["How would you tell a server problem from an app problem?"], kind="scenario"),
    q("pl-scenario", "hard", ["design"], "Scenario: design a notification system that sends email and push messages for orders and must not send the same message twice.", "Create a notification record per event and channel with a unique key, process records from a queue with retries, mark them sent atomically and keep per-user preferences. Monitor failures and handle provider outages with backoff.", ["Unique key per notification", "Queue and retries", "Preferences and monitoring"], ["What if the provider sends it but the response is lost?"], kind="scenario"),
    q("pl-scenario", "easy", ["teamwork"], "Scenario: a teammate's pull request has a bug but they are senior to you. What do you do?", "Review it on the facts, explain the bug with an example or a failing test, ask a question rather than accuse and stay open to being wrong. If it is serious, raise it so it is fixed before merging.", ["Be factual and polite", "Show evidence", "Do not stay silent on serious bugs"], ["How do you take feedback on your own code?"], kind="scenario"),
    q("git", "easy", ["git"], "What do git clone, branch, commit, push and pull request each do in a normal team workflow?", "Clone copies a repository, branch creates a separate line of work, commit saves a snapshot, push uploads commits and a pull request asks teammates to review and merge the branch. Small commits with clear messages help reviews.", ["Each command's role", "Branch per feature", "Review before merge"], ["How do you undo your last local commit?"]),
    q("project", "easy", ["projects"], "Describe a web, mobile or AI project you completed. What did you build yourself, what failed and how did you fix it?", "A strong answer is specific about the goal, stack and your own part, names a real failure and the fix, and says how you tested and shared it.", ["Specific goal and own part", "A real failure and fix", "Testing and delivery"], ["What would you do differently?"], kind="scenario", roles=PL + ["frontend-developer"]),
]


def build():
    return write("purelogics", PL, ITEMS)


if __name__ == "__main__":
    build()
